\operatorname{PrfOK}_{\mathsf{LL}}(\pi,Q)
\Longleftrightarrow Q\in\mathsf{Seq}_{\mathsf{LL}}\land
\exists T,r,\prec,\operatorname{ch},\ell\;
\left[\begin{array}{l}
\pi=(T,r,\prec,\operatorname{ch},\ell)\land
(T,r,\prec,\operatorname{ch})\text{ 满足第 6 节的全部有限有根有序树条件}\\
{}\land\ell:T\to\mathsf{Seq}_{\mathsf{LL}}\land\ell(r)=Q\\
{}\land\forall u\in T\;
(\ell\circ\operatorname{ch}(u),\ell(u))\in\mathsf{Rule}_{\mathsf{LL}}
\end{array}\right].
